text:
1.9 Confrontare i modelli: distorsione, sovradattamento e validazione incrociata
Poiché più modelli possono rappresentare la stessa realtà, dobbiamo confrontarli. In questo libro il modello migliore è, per impostazione predefinita, quello che rappresenta meglio la realtà che intende approssimare per lo scopo in questione, e lo misuriamo con metriche di prestazione calcolate su dati che il modello non ha visto (James et al. 2021, cap. 2). Nell’apprendimento supervisionato le metriche misurano la distanza tra previsioni ed esiti osservati (errore assoluto medio, accuratezza, area sotto la curva ROC…); nell’apprendimento non supervisionato misurano quanto bene viene colta la struttura (silhouette, errore di ricostruzione); nell’apprendimento per rinforzo, la ricompensa cumulata; nella modellazione generativa, la fedeltà, la diversità e la sicurezza di ciò che viene generato. Ogni capitolo introduce le metriche di cui ha bisogno. La prestazione predittiva non è l’unico criterio: apprezziamo anche i modelli che si possono interpretare e usare per rispondere a domande scientifiche (Capitolo 12), e una buona analisi cerca un equilibrio.

Definizione 1.8 (Distorsione, varianza, sovradattamento) Un modello ha un’elevata distorsione (bias) quando le sue ipotesi sono troppo rigide per cogliere l’andamento reale: è sottoadattato (underfitting) e sbaglia in modo sistematico. Ha un’elevata varianza quando è così flessibile da seguire il rumore del suo particolare insieme di addestramento: è sovradattato (overfitting), con un’ottima prestazione sui dati di addestramento e una scarsa prestazione sui dati nuovi. I buoni modelli bilanciano le due cose (James et al. 2021, cap. 2).







Figura 1.9: Una poltrona modellata per adattarsi perfettamente a un solo bambino. È ideale per lui e scomoda, o inutile, per chiunque altro: un modello in sovradattamento è cucito su misura sui dati di addestramento allo stesso modo.



Pensa a una poltrona fatta su misura per un bambino (Figura 1.9): si adatta a ogni curva di quel bambino, e di nessun altro. Un modello in sovradattamento è stato modellato sui pazienti specifici con cui è stato addestrato, comprese le loro particolarità casuali, e si adatta male ai pazienti nuovi.

Troppo semplice, giusto, troppo flessibile. Trenta punti di addestramento (i pallini) provengono da una curva regolare (tratteggiata) più del rumore. Il modello è un polinomio di cui scegli il grado: il grado 1 è una retta; i gradi elevati si piegano molte volte. Osserva l’errore di addestramento e l’errore su 300 nuovi punti di test.

viewof deg = Inputs.range([0, 15], {value: 1, step: 1, label: "Grado del polinomio"})







ofit = {
  function mulberry32(a) { return function() { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a &gt;&gt;&gt; 15, 1 | a); t = t + Math.imul(t ^ t &gt;&gt;&gt; 7, 61 | t) ^ t; return ((t ^ t &gt;&gt;&gt; 14) &gt;&gt;&gt; 0) / 4294967296; }; }
  const rnd = mulberry32(42);
  const gauss = () =&gt; { let u = 0, v = 0; while (u === 0) u = rnd(); v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
  const truth = x =&gt; Math.sin(3 * x) + 0.3 * x;
  const sample = m =&gt; d3.range(m).map(() =&gt; { const x = rnd() * 2 - 1; return {x, y: truth(x) + 0.35 * gauss()}; });
  const train = sample(30), test = sample(300);
  const cheb = (x, d) =&gt; { const T = [1, x]; for (let k = 2; k &lt;= d; k++) T.push(2 * x * T[k - 1] - T[k - 2]); return T.slice(0, d + 1); };
  function fit(d) {
    const m = d + 1, A = d3.range(m).map(() =&gt; new Array(m).fill(0)), bv = new Array(m).fill(0);
    for (const p of train) { const t = cheb(p.x, d); for (let i = 0; i &lt; m; i++) { bv[i] += t[i] * p.y; for (let j = 0; j &lt; m; j++) A[i][j] += t[i] * t[j]; } }
    for (let i = 0; i &lt; m; i++) A[i][i] += 1e-9;
    for (let c = 0; c &lt; m; c++) { let piv = c; for (let r = c + 1; r &lt; m; r++) if (Math.abs(A[r][c]) &gt; Math.abs(A[piv][c])) piv = r;
      [A[c], A[piv]] = [A[piv], A[c]]; [bv[c], bv[piv]] = [bv[piv], bv[c]];
      for (let r = 0; r &lt; m; r++) if (r !== c) { const f = A[r][c] / A[c][c]; for (let k = c; k &lt; m; k++) A[r][k] -= f * A[c][k]; bv[r] -= f * bv[c]; } }
    const w = bv.map((v, i) =&gt; v / A[i][i]);
    const pred = x =&gt; cheb(x, d).reduce((s, t, i) =&gt; s + t * w[i], 0);
    const rmse = data =&gt; Math.sqrt(d3.mean(data, p =&gt; (p.y - pred(p.x)) ** 2));
    return {pred, train: rmse(train), test: rmse(test)};
  }
  const all = d3.range(0, 16).map(d =&gt; ({d, ...fit(d)}));
  return {train, truth, all};
}







{
  const cur = ofit.all[deg];
  const grid = d3.range(-1, 1.0001, 0.01);
  const verdict = deg &lt;= 2 ? "distorsione elevata: troppo semplice per seguire la curva" : deg &lt;= 6 ? "un equilibrio ragionevole" : "varianza elevata: insegue il rumore";
  return html`&lt;p&gt;Grado ${deg}: errore di addestramento &lt;strong&gt;${cur.train.toFixed(3)}&lt;/strong&gt; · errore di test &lt;strong&gt;${cur.test.toFixed(3)}&lt;/strong&gt;: ${verdict}.&lt;/p&gt;`;
}







Plot.plot({
  height: 260, grid: true, y: {domain: [-2.5, 2.5], label: "y"}, x: {label: "x"},
  marks: [
    Plot.line(d3.range(-1, 1.0001, 0.01).map(x =&gt; [x, ofit.truth(x)]), {strokeDasharray: "5,4"}),
    Plot.line(d3.range(-1, 1.0001, 0.005).map(x =&gt; [x, Math.max(-2.5, Math.min(2.5, ofit.all[deg].pred(x)))]), {stroke: "#1f6f8b", strokeWidth: 2.5}),
    Plot.dot(ofit.train, {x: "x", y: "y", r: 3, fill: "currentColor"})
  ]
})







Plot.plot({
  height: 200, grid: true, x: {label: "Grado del polinomio"}, y: {label: "Errore (RMSE)", domain: [0, 1.2]},
  color: {legend: true, domain: ["addestramento", "test"], range: ["#888", "#1f6f8b"]},
  marks: [
    Plot.line(ofit.all, {x: "d", y: d =&gt; Math.min(d.train, 1.2), stroke: () =&gt; "addestramento", strokeWidth: 2}),
    Plot.line(ofit.all, {x: "d", y: d =&gt; Math.min(d.test, 1.2), stroke: () =&gt; "test", strokeWidth: 2}),
    Plot.ruleX([deg], {strokeDasharray: "3,3"})
  ]
})







L’errore di addestramento diminuisce sempre man mano che il modello diventa più flessibile; l’errore di test diminuisce e poi torna a salire. Il grado con l’errore di test più basso è quello da scegliere. Ma abbiamo usato l’insieme di test per fare questa scelta, quindi non è più un giudice imparziale del modello scelto. Il rimedio standard è la validazione incrociata (cross-validation).

Definizione 1.9 (Validazione incrociata) Nella validazione incrociata a \(V\) blocchi (\(V\)-fold cross-validation) i dati di addestramento vengono suddivisi in \(V\) parti (blocchi o fold). A turno, ciascun blocco viene tenuto da parte mentre il modello viene stimato sugli altri \(V-1\) blocchi e valutato su quello escluso; i \(V\) errori vengono poi mediati. Scelte come il grado del polinomio si fanno in base all’errore di validazione incrociata, e l’insieme di test si usa una sola volta, alla fine. Con \(V = n\) si parla di validazione incrociata leave-one-out (lasciane fuori uno) (Stone 1974; James et al. 2021, cap. 5).



  Validazione incrociata a cinque blocchi
  Cinque righe, una per ciascun turno. In ogni riga i dati di addestramento sono disegnati come cinque blocchi; in ogni riga un blocco diverso viene tenuto da parte per la validazione e gli altri quattro sono usati per la stima.

  Turno 1Turno 2Turno 3Turno 4Turno 5








  escluso

Validazione incrociata a cinque blocchi: ogni blocco (evidenziato) viene escluso una volta mentre il modello viene stimato sugli altri quattro.

Distorsione, sovradattamento e validazione incrociata affrontano tutti un’unica domanda: il modello sta apprendendo il segnale o sta memorizzando il rumore? Rispondere onestamente è ciò che rende un modello adatto a informare decisioni reali. Il Capitolo 3 trasforma queste idee in una procedura di lavoro.

La tua prima valutazione onesta. Usa la suddivisione fissa del libro dei dati del Reparto 7 in un insieme di addestramento (1.000 pazienti, 80%) e uno di test (250 pazienti, 20%), poi valuta il modello più semplice possibile: prevedere, per ogni paziente del test, la variazione media della creatinina dei pazienti di addestramento. Riempi lo spazio vuoto con la funzione che calcola una media. L’ultima riga calcola l’errore assoluto medio sull’insieme di test.

RPython

















In R la funzione che calcola la media aritmetica è mean().


prediction &lt;- mean(train$delta_creatinine_48h)


















Le colonne di pandas hanno un metodo .mean().


prediction = train["delta_creatinine_48h"].mean()




R e Python leggono la stessa suddivisione, quindi entrambi danno 0,236 mg/dL. È la prima riga della tabella di confronto che il Capitolo 3 avvia e che ogni capitolo successivo amplia: ogni nuovo modello del Reparto 7 viene giudicato su questi stessi 250 pazienti di test.

3.5 La validazione incrociata, passo per passo
Il Capitolo 1 ha definito la validazione incrociata a \(V\) blocchi (Definizione 1.9); ecco la procedura completa (Stone 1974; James et al. 2021, cap. 5). Prendi l’insieme di addestramento, già diviso in \(V\) blocchi di dimensioni circa uguali (nel Reparto 7, \(V = 5\) blocchi da 200). Poi, per ogni blocco \(v = 1, \dots, V\):

metti da parte il blocco \(v\) come blocco di validazione;
stima il modello sugli altri \(V - 1\) blocchi, compresi tutti i passi che dipendono dai dati (scelta delle variabili, standardizzazione, imputazione; vedi la Sezione 3.6);
prevedi gli esiti del blocco di validazione e calcola la metrica, \(\text{MAE}_v\).

Infine fai la media dei \(V\) risultati:
\[
\text{CV}_{(V)} = \frac{1}{V}\sum_{v=1}^{V} \text{MAE}_v .
\qquad(3.6)\]
Ogni paziente di addestramento viene usato per la validazione esattamente una volta e per la stima \(V - 1\) volte. La dispersione dei \(V\) errori dei blocchi dice di quanto si sposterebbe la stima con una suddivisione diversa; il suo errore standard, la deviazione standard degli errori dei blocchi divisa per \(\sqrt{V}\), è una misura approssimativa di questa incertezza (Hastie, Tibshirani, e Friedman 2009, cap. 7).

Guarda la validazione incrociata all’opera. Ogni punto è uno dei 1.000 pazienti di addestramento del Reparto 7. A ogni turno un blocco (colorato) viene escluso, il modello viene stimato sugli altri quattro (grigi) e il suo MAE viene calcolato sul blocco escluso. Il turno 6 combina i cinque risultati. Scegli un modello, poi premi Avvia o sposta il cursore. Nota che l’insieme di test non partecipa mai.

icu3 = FileAttachment("data/icu_aki.csv").csv({typed: true})
split3 = FileAttachment("data/splits/ward7_split.csv").csv({typed: true})
w7 = icu3.map((d, i) =&gt; ({...d, set: split3[i].set, fold: split3[i].fold,
                          sx: d.sofa + (((i * 7919) % 101) / 101 - 0.5) * 0.6}))
w7train = w7.filter(d =&gt; d.set === "train")
viewof cvModel = Inputs.radio(["Modello della media", "Retta in funzione del SOFA"], {value: "Modello della media", label: "Modello"})
viewof cvPlay = Inputs.toggle({label: "Avvia", value: false})
viewof cvManual = Inputs.range([1, 6], {value: 1, step: 1, label: "Turno (6 = combina)"})



















































cvRound = {
  if (!cvPlay) { yield cvManual; return; }
  let r = 0;
  while (true) { yield (r % 6) + 1; r += 1; await Promises.delay(1400); }
}
cvFits = {
  const fitFn = rows =&gt; {
    const ys = rows.map(d =&gt; d.delta_creatinine_48h), my = d3.mean(ys);
    if (cvModel === "Modello della media") return {a: my, b: 0};
    const xs = rows.map(d =&gt; d.sofa), mx = d3.mean(xs);
    const b = d3.sum(xs, (x, i) =&gt; (x - mx) * (ys[i] - my)) / d3.sum(xs, x =&gt; (x - mx) ** 2);
    return {a: my - b * mx, b};
  };
  return [1, 2, 3, 4, 5].map(v =&gt; {
    const f = fitFn(w7train.filter(d =&gt; d.fold !== v));
    const val = w7train.filter(d =&gt; d.fold === v);
    return {fold: v, a: f.a, b: f.b, mae: d3.mean(val, d =&gt; Math.abs(d.delta_creatinine_48h - (f.a + f.b * d.sofa)))};
  });
}
{
  const r = cvRound;
  const box = (label, sub, on, dashed) =&gt; html`&lt;div style="flex:1; min-width:58px; padding:6px 4px; text-align:center; border-radius:6px; font-size:0.82rem; border:1.5px ${dashed ? "dashed" : "solid"} ${on ? "var(--aihs-accent)" : "var(--aihs-border)"}; background:${on ? "var(--aihs-accent-soft)" : "transparent"}"&gt;&lt;strong&gt;${label}&lt;/strong&gt;&lt;br&gt;${sub}&lt;/div&gt;`;
  const cells = cvFits.map(f =&gt; box(`Blocco ${f.fold}`,
    r === 6 ? `MAE ${f.mae.toFixed(3)}` : (r === f.fold ? "validazione" : "stima"), r === f.fold || r === 6, false));
  const cv = d3.mean(cvFits, f =&gt; f.mae), se = d3.deviation(cvFits, f =&gt; f.mae) / Math.sqrt(5);
  if (r === 6 && window.aihs) window.aihs.complete("ch03-tryit-cv");
  return html`&lt;div style="display:flex; flex-wrap:wrap; gap:6px; margin:0.4rem 0"&gt;${cells}${box("Insieme di test", "250 · chiuso", false, true)}&lt;/div&gt;
  &lt;p&gt;${r &lt; 6
    ? html`Turno ${r}: stimato sui blocchi ${[1, 2, 3, 4, 5].filter(v =&gt; v !== r).join(", ")}; MAE sul blocco ${r} = &lt;strong&gt;${cvFits[r - 1].mae.toFixed(3)}&lt;/strong&gt; mg/dL.`
    : html`MAE in validazione incrociata = media dei cinque = &lt;strong&gt;${cv.toFixed(3)}&lt;/strong&gt; mg/dL (errore standard ${se.toFixed(3)}).`}&lt;/p&gt;`;
}























{
  const r = cvRound, lines = r === 6 ? cvFits : [cvFits[r - 1]];
  return Plot.plot({
    height: 290, grid: true, color: {type: "identity"},
    x: {label: "Punteggio SOFA al ricovero", domain: [-0.5, 18.5]},
    y: {label: "Variazione della creatinina in 48 h (mg/dL)"},
    marks: [
      Plot.dot(w7train, {x: "sx", y: "delta_creatinine_48h", r: 1.8,
        fill: d =&gt; (r === 6 || d.fold === r) ? "#1f6f8b" : "#999",
        fillOpacity: d =&gt; (r === 6 || d.fold === r) ? 0.6 : 0.25}),
      ...lines.map(f =&gt; Plot.line([[0, f.a], [18, f.a + 18 * f.b]], {stroke: "#b35c00", strokeWidth: r === 6 ? 1.5 : 3}))
    ]
  });
}







Plot.plot({
  height: 170, grid: true, marginLeft: 50,
  x: {label: "Blocco di validazione", domain: [1, 2, 3, 4, 5], type: "band"},
  y: {label: "MAE (mg/dL)", domain: [0, 0.3]},
  marks: [
    Plot.barY(cvFits.filter(f =&gt; cvRound === 6 || f.fold &lt;= cvRound), {x: "fold", y: "mae", fill: "#1f6f8b", fillOpacity: 0.7}),
    cvRound === 6 ? Plot.ruleY([d3.mean(cvFits, f =&gt; f.mae)], {stroke: "#b35c00", strokeWidth: 2}) : null,
    Plot.ruleY([0])
  ]
})








I cinque errori dei blocchi non sono identici; differiscono fino a qualche centesimo di mg/dL, perché alcuni blocchi contengono per caso pazienti più facili di altri. Questa variabilità è proprio il motivo per cui una singola suddivisione può trarre in inganno, e per cui fare la media sui blocchi dà una stima più stabile.
Quanti blocchi? Con un \(V\) più grande ogni stima usa una parte maggiore dei dati, quindi la stima dell’errore si avvicina a quella di un modello addestrato su tutti i dati; ma le stime si sovrappongono di più, i \(V\) errori si somigliano di più e il calcolo cresce. La validazione incrociata leave-one-out (\(V = n\)) è il caso estremo: quasi priva di distorsione, ma variabile e costosa per i modelli lenti. Cinque o dieci blocchi sono il compromesso abituale (James et al. 2021, cap. 5; Hastie, Tibshirani, e Friedman 2009, cap. 7). Due perfezionamenti sono comuni. La validazione incrociata ripetuta riesegue l’intera procedura con diverse assegnazioni casuali dei blocchi e ne fa la media, il che rende la stima ancora più stabile. I blocchi stratificati mantengono simile in ogni blocco la proporzione di un esito (per esempio AKI sì/no) (Kuhn e Johnson 2013, cap. 4).
I blocchi devono rispettare la struttura dei dati. Se un paziente contribuisce con più righe, come un partecipante di HomeBeat con una riga al giorno, tutte le righe di quella persona devono stare nello stesso blocco; altrimenti il modello viene in parte validato proprio sulle persone su cui è stato stimato. La stessa logica, applicata agli ospedali, dà la validazione incrociata lasciando fuori un ospedale alla volta (leave-one-site-out): si stima il modello su tre ospedali del Reparto 7, lo si verifica sul quarto e si ruota. È la validazione interna-esterna della Sezione 3.2, e la useremo alla fine di questo capitolo.

Con la validazione incrociata a cinque blocchi sui 1.000 pazienti di addestramento del Reparto 7, quante volte viene stimato il modello, e su quanti pazienti ogni volta?

Una volta, su 1.000 pazienti Questa è un’unica stima sull’intero insieme di addestramento: produce un modello ma nessuna stima onesta dell’errore.
Cinque volte, su 800 pazienti ogni volta Esatto. Ogni turno esclude un blocco da 200 e stima il modello sugli 800 rimanenti. (Dopo che la validazione incrociata ha guidato le scelte, di solito il modello scelto viene stimato un’ultima volta su tutti i 1.000.)
Cinque volte, su 200 pazienti ogni volta È il contrario: ogni stima usa quattro blocchi (800 pazienti) e viene validata sul quinto (200).
1.000 volte, su 999 pazienti ogni volta Questa è la validazione incrociata leave-one-out, il caso \(V = n\).

3.7 \(k\) vicini più prossimi: un primo metodo di apprendimento
Finora i nostri modelli sono stati medie e rette. Ecco un’idea diversa, vicina al modo in cui i clinici ragionano in base all’esperienza: per prevedere che cosa succederà ad Aoife, guarda i pazienti del passato che le somigliavano di più e osserva che cosa è successo a loro.

Definizione 3.5 (\(k\) vicini più prossimi) Il metodo dei \(k\) vicini più prossimi (\(k\)NN, dall’inglese \(k\)-nearest neighbours) prevede l’esito di una nuova istanza \(\mathbf{x}\) trovando le \(k\) istanze di addestramento più vicine a essa, l’insieme \(N_k(\mathbf{x})\), e facendo la media dei loro esiti (per un esito numerico) o una votazione (per una categoria):
\[
\hat y(\mathbf{x}) = \frac{1}{k}\sum_{i \in N_k(\mathbf{x})} y_i .
\qquad(3.7)\]
“Più vicine” si misura con una distanza tra vettori di variabili, di solito la distanza euclidea sulle variabili standardizzate (Cover e Hart 1967; James et al. 2021, cap. 2).

Il \(k\)NN ha una proprietà insolita: non ha un passo di stima. L’“addestramento” consiste nel memorizzare i pazienti di addestramento; tutto il lavoro avviene al momento della previsione. Due ingredienti richiedono attenzione.
La distanza. Nel Reparto 7 usiamo due predittori, il punteggio SOFA e la creatinina basale, e misuriamo quanto due pazienti sono lontani con la normale distanza in linea retta (euclidea) nel piano formato dai due. Il Capitolo 10 è dedicato alle distanze e a ciò che succede loro quando i predittori sono molti; per ora il piano basta.
La scala. Il SOFA va da 0 a 18 punti; la creatinina basale da circa 0,4 a 3 mg/dL. Con i valori grezzi, un punto di SOFA conterebbe quanto un intero mg/dL di creatinina, solo per via delle unità. Per questo ogni predittore viene standardizzato: si sottrae la media di addestramento e si divide il risultato per la deviazione standard di addestramento, mettendo entrambi su una scala confrontabile. Con la standardizzazione le previsioni non dipendono dalle unità. Senza, invece, sì: se la creatinina viene registrata in µmol/L (1 mg/dL = 88,4 µmol/L), i suoi numeri grandi dominano la distanza e il MAE in validazione incrociata del \(k\)NN non standardizzato peggiora da 0,181 a 0,189 mg/dL, mentre il \(k\)NN standardizzato dà 0,179 con entrambe le unità. Nota la parola addestramento: le medie e le deviazioni standard si apprendono solo dalle righe di addestramento (dai blocchi di stima durante la validazione incrociata), altrimenti è la standardizzazione stessa a causare una fuga di informazione (Sezione 3.6).
Il numero di vicini \(k\) controlla la flessibilità. Con \(k = 1\) ogni previsione copia un unico paziente del passato: il modello segue ogni accidente dei dati, l’estremo ad alta varianza della Definizione 1.8. Il suo errore di addestramento è vicino a zero, perché ogni paziente di addestramento è (quasi) il vicino più prossimo di sé stesso; nel Reparto 7 è di 0,072 mg/dL. Il suo errore in validazione incrociata è di 0,254, peggiore di quello del modello della media. Man mano che \(k\) cresce, le previsioni diventano medie su più pazienti e si fanno più regolari; con \(k\) pari all’intero insieme di addestramento ogni previsione è la media di addestramento, l’estremo ad alta distorsione. Da qualche parte nel mezzo c’è il compromesso migliore, e solo dati che il modello non ha visto possono dirci dove.

Pazienti come Aoife. Lo sfondo mostra la previsione del \(k\)NN per la variazione della creatinina a 48 ore per ogni combinazione di SOFA e creatinina basale; i punti grigi sono i 1.000 pazienti di addestramento e i tre punti con l’etichetta sono i pazienti di stasera. I punti cerchiati sono i \(k\) vicini più prossimi di Aoife. Il grafico in basso mostra l’errore di addestramento e l’errore in validazione incrociata a cinque blocchi per ogni \(k\). Sposta \(k\) e guarda la mappa passare da frastagliata a regolare. Obiettivo: trovare un \(k\) il cui MAE in validazione incrociata sia entro 0,001 mg/dL dal minimo possibile.

knnCurve = FileAttachment("data/precomputed/ch03/knn_curve.csv").csv({typed: true})
knnSummary = FileAttachment("data/precomputed/ch03/summary.json").json()
tonight3 = FileAttachment("data/ward7_tonight.csv").csv({typed: true})
viewof kNN = Inputs.range([1, 150], {value: 1, step: 1, label: "Numero di vicini k"})






























knnPrep = {
  const tr = w7train, K = 150;
  const xs = tr.map(d =&gt; d.sofa), cs = tr.map(d =&gt; d.baseline_creat), ys = tr.map(d =&gt; d.delta_creatinine_48h);
  const mx = d3.mean(xs), sx = d3.deviation(xs), mc = d3.mean(cs), sc = d3.deviation(cs);
  const zx = xs.map(x =&gt; (x - mx) / sx), zc = cs.map(c =&gt; (c - mc) / sc);
  const neigh = (s, c) =&gt; {
    const a = (s - mx) / sx, b = (c - mc) / sc;
    const d = zx.map((z, i) =&gt; ({i, d: (z - a) ** 2 + (zc[i] - b) ** 2}));
    d.sort((p, q) =&gt; p.d - q.d || p.i - q.i);
    const cum = new Float64Array(K); let acc = 0;
    for (let j = 0; j &lt; K; j++) { acc += ys[d[j].i]; cum[j] = acc; }
    return {cum, idx: d.slice(0, K).map(e =&gt; e.i)};
  };
  const c0 = 0.4, c1 = 2.6, ny = 28, cs0 = (c1 - c0) / ny, grid = [];
  for (let s = 0; s &lt;= 18; s++) for (let b = 0; b &lt; ny; b++) {
    const c = c0 + (b + 0.5) * cs0;
    grid.push({x1: s - 0.5, x2: s + 0.5, y1: c0 + b * cs0, y2: c0 + (b + 1) * cs0, cum: neigh(s, c).cum});
  }
  const pts = tonight3.map(p =&gt; ({name: p.name.split(" ")[0], sofa: p.sofa, creat: p.baseline_creat, ...neigh(p.sofa, p.baseline_creat)}));
  const jit = tr.map((d, i) =&gt; ({sx: d.sofa + (((i * 7919) % 101) / 101 - 0.5) * 0.6, c: d.baseline_creat}));
  return {grid, pts, jit};
}







