boost = {
  const tr = icuT.filter(d =&gt; d.set === "train").map(d =&gt; ({x: d.sofa, y: d.delta_creatinine_48h}));
  const te = icuT.filter(d =&gt; d.set === "test").map(d =&gt; ({x: d.sofa, y: d.delta_creatinine_48h}));
  const xs = Array.from(new Set(tr.map(d =&gt; d.x))).sort((a, b) =&gt; a - b);
  const thr = xs.slice(0, -1).map((v, i) =&gt; (v + xs[i + 1]) / 2);
  const F0 = d3.mean(tr, d =&gt; d.y);
  const F = tr.map(() =&gt; F0), G = te.map(() =&gt; F0);
  const mae = (data, P) =&gt; d3.mean(data, (d, i) =&gt; Math.abs(d.y - P[i]));
  const stumps = [], hist = [{m: 0, set: "addestramento", mae: mae(tr, F)}, {m: 0, set: "test", mae: mae(te, G)}];
  for (let m = 1; m &lt;= 100; m++) {
    const r = tr.map((d, i) =&gt; d.y - F[i]);
    let best = null;
    for (const s of thr) {
      let nl = 0, sl = 0, nr = 0, sr = 0, ssl = 0, ssr = 0;
      tr.forEach((d, i) =&gt; { if (d.x &lt; s) { nl++; sl += r[i]; ssl += r[i] ** 2; } else { nr++; sr += r[i]; ssr += r[i] ** 2; } });
      if (!nl || !nr) continue;
      const sse = (ssl - sl * sl / nl) + (ssr - sr * sr / nr);
      if (!best || sse &lt; best.sse) best = {sse, s, a: sl / nl, b: sr / nr};
    }
    stumps.push(best);
    tr.forEach((d, i) =&gt; { F[i] += bEta * (d.x &lt; best.s ? best.a : best.b); });
    te.forEach((d, i) =&gt; { G[i] += bEta * (d.x &lt; best.s ? best.a : best.b); });
    hist.push({m, set: "addestramento", mae: mae(tr, F)}, {m, set: "test", mae: mae(te, G)});
  }
  const fit = (x, M) =&gt; F0 + bEta * d3.sum(stumps.slice(0, M), st =&gt; x &lt; st.s ? st.a : st.b);
  return {tr, F0, stumps, hist, fit};
}







