    for (let r = 0; r &lt; p; r++) if (r !== c) { const f = A[r][c] / A[c][c]; for (let k = c; k &lt;= p; k++) A[r][k] -= f * A[c][k]; }
  }
  return A.map((row, r) =&gt; row[p] / row[r]);
}
sim = {
  let s0 = 2026 + draw * 7919;
  const rnd = () =&gt; { s0 |= 0; s0 = s0 + 0x6D2B79F5 | 0; let t = Math.imul(s0 ^ s0 &gt;&gt;&gt; 15, 1 | s0); t = t + Math.imul(t ^ t &gt;&gt;&gt; 7, 61 | t) ^ t; return ((t ^ t &gt;&gt;&gt; 14) &gt;&gt;&gt; 0) / 4294967296; };
  const u = hbw.map(() =&gt; rnd());
  const zs = arr =&gt; { const m = d3.mean(arr), s = d3.deviation(arr); return arr.map(v =&gt; (v - m) / s); };
  const kind = mech.slice(0, 4);
  const driver = kind === "MCAR" ? hbw.map(() =&gt; 0) : kind === "MAR:" ? zs(hbw.map(d =&gt; d.age)) : zs(hbw.map(d =&gt; d.hrv)).map(v =&gt; -v);
  const s = kind === "MCAR" ? 0 : strength;
  const lg = x =&gt; 1 / (1 + Math.exp(-x));
  let lo = -30, hi = 30;
  for (let k = 0; k &lt; 60; k++) { const mid = (lo + hi) / 2; if (d3.mean(driver, v =&gt; lg(mid + s * v)) &lt; frac) lo = mid; else hi = mid; }
  const a = (lo + hi) / 2;
  const rows = hbw.map((d, i) =&gt; ({...d, status: u[i] &lt; lg(a + s * driver[i]) ? "missing" : "recorded"}));
  const obs = rows.filter(d =&gt; d.status === "recorded");
  const b = ols4(obs.map(d =&gt; [1, d.age, d.frailty, d.baseline_inflammation]), obs.map(d =&gt; d.hrv));
  const pred = d =&gt; b[0] + b[1] * d.age + b[2] * d.frailty + b[3] * d.baseline_inflammation;
  return {rows, truth: d3.mean(rows, d =&gt; d.hrv), rec: d3.mean(obs, d =&gt; d.hrv),
          reg: d3.mean(rows, d =&gt; d.status === "missing" ? pred(d) : d.hrv),
          nmiss: rows.length - obs.length, kind};
}
{
  const bRec = sim.rec - sim.truth, bReg = sim.reg - sim.truth;
  const hit = sim.kind === "MNAR" && Math.abs(bReg) &gt; 1;
  if (hit && window.aihs) window.aihs.complete("ch09-tryit-mechanism");
  return html`&lt;p&gt;${sim.nmiss} valori di HRV mancanti su 500. Media vera: &lt;strong&gt;${sim.truth.toFixed(1)} ms&lt;/strong&gt;
  · solo valori registrati: &lt;strong&gt;${sim.rec.toFixed(1)} ms&lt;/strong&gt; (distorsione ${bRec &gt;= 0 ? "+" : ""}${bRec.toFixed(1)})
  · riempimento con la regressione: &lt;strong&gt;${sim.reg.toFixed(1)} ms&lt;/strong&gt; (distorsione ${bReg &gt;= 0 ? "+" : ""}${bReg.toFixed(1)})
  ${hit ? "&lt;br&gt;✓ Trovato: quando le lacune dipendono dalla HRV stessa, le variabili osservate non possono ripararle del tutto." : ""}&lt;/p&gt;`;
}





















