wiBeta = Object.fromEntries(coefs12.map(d =&gt; [d.term, d.estimate]))
viewof wSofa = Inputs.range([0, 18], {value: 6, step: 1, label: "Punteggio SOFA"})
viewof wLact = Inputs.range([0.5, 8], {value: 2.1, step: 0.1, label: "Lattato (mmol/L)"})
viewof wCreat = Inputs.range([0.4, 2.5], {value: 1.0, step: 0.05, label: "Creatinina di base (mg/dL)"})
viewof wMap = Inputs.range([40, 100], {value: 66, step: 1, label: "PAM minima (mmHg), modificabile"})
