bandit = {
  function mulberry32(a) { return function() { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a &gt;&gt;&gt; 15, 1 | a); t = t + Math.imul(t ^ t &gt;&gt;&gt; 7, 61 | t) ^ t; return ((t ^ t &gt;&gt;&gt; 14) &gt;&gt;&gt; 0) / 4294967296; }; }
  const gauss = r =&gt; { let u = 0; while (u === 0) u = r(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * r()); };
  function rgamma(a, r) {            // Marsaglia–Tsang, valido per a &gt;= 1
    const d = a - 1 / 3, c = 1 / Math.sqrt(9 * d);
    for (;;) {
      let x, v; do { x = gauss(r); v = 1 + c * x; } while (v &lt;= 0);
      v = v * v * v; const u = r();
      if (u &lt; 1 - 0.0331 * x ** 4 || Math.log(u) &lt; 0.5 * x * x + d * (1 - v + Math.log(v))) return d * v;
    }
  }
  const rbeta = (a, b, r) =&gt; { const x = rgamma(a, r), y = rgamma(b, r); return x / (x + y); };
  const p = [bdP1, bdP2, bdP3], K = 3, T = bdT, runs = bdAvg ? 100 : 1, best = Math.max(...p);
  const names = ["Allocazione uguale", "Greedy", "ε-greedy", "Campionamento di Thompson"];
  const regret = names.map(() =&gt; new Float64Array(T)), alloc = names.map(() =&gt; [0, 0, 0]), engaged = names.map(() =&gt; 0);
  for (let run = 0; run &lt; runs; run++) {
    const env = mulberry32(9001 + 7919 * bdNew + run);
    const U = Array.from({length: T}, () =&gt; [env(), env(), env()]);      // gli stessi partecipanti per tutti
    names.forEach((nm, j) =&gt; {
      const r = mulberry32(31 + 101 * j + 1009 * run + 7 * bdNew);
      const n = [0, 0, 0], s = [0, 0, 0]; let cum = 0;
      for (let t = 0; t &lt; T; t++) {
        let arm;
        if (j === 0) arm = Math.floor(r() * K);
        else if (t &lt; K) arm = t;
        else if (j === 3) { const th = [0, 1, 2].map(i =&gt; rbeta(1 + s[i], 1 + n[i] - s[i], r)); arm = th.indexOf(Math.max(...th)); }
        else {
          const est = [0, 1, 2].map(i =&gt; s[i] / n[i]), m = Math.max(...est), ties = [0, 1, 2].filter(i =&gt; est[i] === m);
          arm = ties[Math.floor(r() * ties.length)];
          if (j === 2 && r() &lt; bdEps) arm = Math.floor(r() * K);
        }
        const y = U[t][arm] &lt; p[arm] ? 1 : 0;
        n[arm]++; s[arm] += y; cum += best - p[arm];
        regret[j][t] += cum / runs; alloc[j][arm] += 1 / runs; engaged[j] += y / runs;
      }
    });
  }
  const step = Math.max(1, Math.floor(T / 200));
  const series = names.flatMap((nm, j) =&gt; d3.range(0, T, step).concat([T - 1]).map(t =&gt; ({t: t + 1, strategy: nm, regret: regret[j][t]})));
  return {names, alloc, engaged, T, p, series, final: names.map((nm, j) =&gt; regret[j][T - 1])};
}







