14.4 Imparare dall’esperienza: Q-learning
L’iterazione dei valori ha bisogno delle probabilità di transizione della Tabella 14.2. Per un paziente reale nessuno le conosce. Un agente può trovare una buona politica semplicemente agendo e osservando che cosa succede? È ciò che fa l’apprendimento per rinforzo senza modello (model-free), e il Q-learning ne è l’algoritmo classico (Watkins e Dayan 1992).

Definizione 14.8 (Q-learning) Il Q-learning mantiene una tabella di stime \(\hat Q(s, a)\), una per ogni stato e azione, tutte inizialmente pari a zero. Dopo ogni passo (stato \(s\), azione \(a\), ricompensa \(r\), stato successivo \(s'\)) sposta la stima verso un obiettivo meglio informato:
\[
\hat Q(s, a) \leftarrow \hat Q(s, a) + \eta\,\Bigl[\, \underbrace{r + \gamma \max_{a'} \hat Q(s', a')}_{\text{obiettivo}} - \hat Q(s, a) \,\Bigr],
\qquad(14.5)\]
dove \(\eta\) è l’ampiezza del passo. Di solito le azioni vengono scelte in modo \(\epsilon\)-greedy a partire dalla tabella attuale. Se ogni coppia stato–azione continua a essere provata e l’ampiezza del passo si riduce in modo adeguato, le stime convergono a \(Q^*\) (Watkins e Dayan 1992; Sutton e Barto 2018, cap. 6).

Osserva la forma: nuova stima = vecchia stima + passo × (obiettivo − vecchia stima), come nella Equazione 14.1. L’obiettivo è una versione a un passo dell’equazione di ottimalità di Bellman: la ricompensa effettivamente ricevuta più il valore scontato della migliore azione nello stato effettivamente raggiunto, secondo la stima attuale. Non compare alcuna probabilità di transizione; l’ambiente ne fornisce dei campioni, un passo alla volta. È il \(\max\) nell’obiettivo a rendere il Q-learning off-policy: impara il valore dell’agire in modo greedy anche mentre esplora, così i passi esplorativi non guastano ciò che impara.
Un passo svolto. Supponi che l’agente sia in “10–14, bassa”, con stime attuali di \(-0.4\), \(0.8\) e \(1.6\) per ridurre, mantenere e aumentare. Aumenta la velocità; la glicemia scende a 6–10 (ricompensa \(+1\)) e lo stato successivo è “6–10, media”, le cui stime sono \(2.1\), \(2.9\) e \(1.2\). Con \(\eta = 0.1\) e \(\gamma = 0.9\) l’obiettivo è \(1 + 0.9 \times 2.9 = 3.61\), l’errore è \(3.61 - 1.6 = 2.01\) e la stima diventa \(1.6 + 0.1 \times 2.01 = 1.801\). Programmerai questo passo nella missione qui sotto.

Guarda un agente che impara a dosare. Ogni cella è uno stato del problema giocattolo: fascia di glicemia (righe) e velocità di infusione (colonne). La freccia mostra l’azione che l’agente ritiene migliore in quel momento (← ridurre, • mantenere, → aumentare); il colore mostra quanto l’agente si aspetta di raccogliere a partire da quello stato (blu è buono, rosso è cattivo). Il contorno spesso indica dove si trova ora la paziente simulata. Premi Un passo qualche volta e leggi l’aggiornamento qui sotto: è la Equazione 14.5 con i numeri. Poi addestra l’agente per centinaia di episodi (un episodio dura 24 ore: 12 passi da uno stato iniziale casuale). Un ✓ indica uno stato in cui la scelta dell’agente è buona quanto quella della politica ottima della Tabella 14.3 (entro 0,05). Obiettivo: almeno 18 stati su 20 con ✓ dopo 50 o più episodi. Poi porta ε a 0 e reimposta: che cosa succede senza esplorazione?

mdpSpec = FileAttachment("data/precomputed/ch14/insulin_mdp.json").json()







mdp = {
  const M = mdpSpec.moves, gamma = mdpSpec.gamma, S = 20, A = 3;
  const sid = (g, r) =&gt; r * 5 + g, band = s =&gt; s % 5, rate = s =&gt; Math.floor(s / 5);
  const bandLab = ["&lt; 4", "4–6", "6–10", "10–14", "&gt; 14"], rateLab = ["spenta", "bassa", "media", "alta"];
  function next(s, a, rew) {                 // a: 0 ridurre, 1 mantenere, 2 aumentare
    const r2 = Math.min(3, Math.max(0, rate(s) + a - 1)), g = band(s), out = [];
    for (let m = 0; m &lt; 3; m++) { const g2 = Math.min(4, Math.max(0, g + m - 1)); out.push([M[r2][m], sid(g2, r2), rew[g2]]); }
    return out;
  }
  function solve(rew) {
    let V = new Array(S).fill(0), Q = null;
    for (let k = 0; k &lt; 3000; k++) {
      Q = d3.range(S).map(s =&gt; d3.range(A).map(a =&gt; d3.sum(next(s, a, rew), ([p, s2, r]) =&gt; p * (r + gamma * V[s2]))));
      const V2 = Q.map(q =&gt; Math.max(...q)), diff = d3.max(V2, (v, i) =&gt; Math.abs(v - V[i]));
      V = V2; if (diff &lt; 1e-10) break;
    }
    const policy = Q.map(q =&gt; q.indexOf(Math.max(...q)));
    return {V, Q, policy};
  }
  function evaluate(policy) {                // occupazione esatta su 24 ore partendo da glicemia 10-14, infusione spenta
    let d = new Array(S).fill(0); d[sid(3, 0)] = 1; const acc = {inRange: 0, hypo: 0, hyper: 0};
    for (let t = 0; t &lt; 12; t++) {
      const d2 = new Array(S).fill(0);
      for (let s = 0; s &lt; S; s++) if (d[s] &gt; 0) for (const [p, s2] of next(s, policy[s], [0, 0, 0, 0, 0])) d2[s2] += d[s] * p;
      d = d2;
      for (let s = 0; s &lt; S; s++) { const g = band(s); if (g === 2) acc.inRange += d[s] / 12; if (g === 0) acc.hypo += d[s] / 12; if (g &gt;= 3) acc.hyper += d[s] / 12; }
    }
    return acc;
  }
  const arrows = ["←", "•", "→"];
  // Con l'infusione 'spenta' ridurre non cambia nulla, e alla velocità 'alta' nemmeno aumentare: mostrali come 'mantenere'.
  const eff = (s, a) =&gt; (rate(s) === 0 && a === 0) || (rate(s) === 3 && a === 2) ? 1 : a;
  // Disegna la griglia 5 x 4 degli stati. cellFn(s) -&gt; {fill, label, corner, current, faded}
  function grid(cellFn, aria) {
    const cw = 104, ch = 58, x0 = 92, y0 = 44, W = x0 + 4 * cw + 12, H = y0 + 5 * ch + 34;
    const svg = d3.create("svg").attr("viewBox", `0 0 ${W} ${H}`).attr("class", "aihs-svg")
      .attr("role", "img").attr("aria-label", aria).style("max-width", "560px");
    rateLab.forEach((r, j) =&gt; svg.append("text").attr("x", x0 + j * cw + cw / 2).attr("y", y0 - 10).attr("text-anchor", "middle").attr("font-size", 13).text(r));
    svg.append("text").attr("x", x0 + 2 * cw).attr("y", 14).attr("text-anchor", "middle").attr("font-size", 13).attr("font-weight", 700).text("Velocità di infusione dell'insulina →");
    for (let g = 4; g &gt;= 0; g--) {
      const row = 4 - g;
      svg.append("text").attr("x", x0 - 8).attr("y", y0 + row * ch + ch / 2 + 4).attr("text-anchor", "end").attr("font-size", 13)
        .attr("font-weight", g === 2 ? 700 : 400).text(bandLab[g] + (g === 2 ? " ★" : ""));
      for (let r = 0; r &lt; 4; r++) {
        const s = sid(g, r), c = cellFn(s), x = x0 + r * cw, y = y0 + row * ch;
        svg.append("rect").attr("x", x + 2).attr("y", y + 2).attr("width", cw - 4).attr("height", ch - 4).attr("rx", 6)
          .attr("fill", c.fill).style("stroke", c.current ? "var(--aihs-accent, #1f6f8b)" : "currentColor")
          .attr("stroke-width", c.current ? 4 : 0.6).attr("opacity", c.faded ? 0.55 : 1);
        svg.append("text").attr("x", x + cw / 2).attr("y", y + ch / 2 + 8).attr("text-anchor", "middle").attr("font-size", 24)
          .attr("font-weight", 700).style("fill", "#111").text(c.label);
        if (c.corner) svg.append("text").attr("x", x + cw - 9).attr("y", y + 17).attr("text-anchor", "end").attr("font-size", 12).style("fill", "#111").text(c.corner);
        if (c.left) svg.append("text").attr("x", x + 9).attr("y", y + 17).attr("font-size", 11).style("fill", "#333").text(c.left);
      }
    }
    svg.append("text").attr("x", 8).attr("y", y0 + 5 * ch + 24).attr("font-size", 12).attr("class", "muted").text("Righe: glicemia (mmol/L), ★ = intervallo obiettivo.");
    return svg.node();
  }
  const colour = d3.scaleLinear().domain([-12, 0, 5]).range(["#e8a39b", "#f2f2f2", "#8fc1d4"]).clamp(true);
  return {S, A, sid, band, rate, bandLab, rateLab, next, solve, evaluate, arrows, eff, grid, colour, gamma};
}







qlStepper = {
  const {S, A, band, rate, bandLab, rateLab, next, solve, arrows, eff, grid, colour, gamma} = mdp;
  const rew = mdpSpec.presets.clinical, opt = solve(rew), steps = 12;
  function mulberry32(a) { return function() { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a &gt;&gt;&gt; 15, 1 | a); t = t + Math.imul(t ^ t &gt;&gt;&gt; 7, 61 | t) ^ t; return ((t ^ t &gt;&gt;&gt; 14) &gt;&gt;&gt; 0) / 4294967296; }; }
  const argmax = q =&gt; { let b = 0; for (let i = 1; i &lt; q.length; i++) if (q[i] &gt; q[b]) b = i; return b; };
  const lab = s =&gt; `${bandLab[band(s)]} | ${rateLab[rate(s)]}`;
  const actName = ["ridurre", "mantenere", "aumentare"];
  let rnd, Q, s, t, ep, last, done = false;
  function reset() { rnd = mulberry32(2014); Q = d3.range(S).map(() =&gt; [0, 0, 0]); s = Math.floor(rnd() * S); t = 0; ep = 0; last = null; }
  function step(eps, eta) {
    if (t === steps) { t = 0; ep++; s = Math.floor(rnd() * S); }
    const explore = rnd() &lt; eps, a = explore ? Math.floor(rnd() * A) : argmax(Q[s]);
    const outs = next(s, a, rew), u = rnd();
    let k = 0, acc = outs[0][0]; while (k &lt; 2 && u &gt;= acc) { k++; acc += outs[k][0]; }
    const [, s2, r] = outs[k], old = Q[s][a], mx = Math.max(...Q[s2]), target = r + gamma * mx;
    Q[s][a] = old + eta * (target - old);
    last = {s, a, s2, r, old, mx, target, nw: Q[s][a], explore, eta};
    s = s2; t++;
  }
  const nearOpt = () =&gt; d3.range(S).filter(x =&gt; opt.Q[x][argmax(Q[x])] &gt;= opt.V[x] - 0.05).length;
  reset();
  const root = html`&lt;div&gt;
    &lt;div style="display:flex;flex-wrap:wrap;gap:0.4rem;margin:0.3rem 0 0.6rem"&gt;
      &lt;button type="button" class="btn btn-sm btn-outline-primary" data-n="1"&gt;Un passo&lt;/button&gt;
      &lt;button type="button" class="btn btn-sm btn-outline-primary" data-n="ep"&gt;Un episodio&lt;/button&gt;
      &lt;button type="button" class="btn btn-sm btn-outline-primary" data-n="50"&gt;+50 episodi&lt;/button&gt;
      &lt;button type="button" class="btn btn-sm btn-outline-primary" data-n="500"&gt;+500 episodi&lt;/button&gt;
