    &lt;/div&gt;
    &lt;div style="display:flex;flex-wrap:wrap;gap:1.2rem;font-size:0.9rem;align-items:center"&gt;
      &lt;label&gt;Esplorazione ε &lt;input type="range" min="0" max="0.5" step="0.05" value="0.2" name="eps" aria-label="Tasso di esplorazione epsilon"&gt; &lt;output name="epsOut"&gt;0.20&lt;/output&gt;&lt;/label&gt;
      &lt;label&gt;Ampiezza del passo η &lt;input type="range" min="0.05" max="0.5" step="0.05" value="0.1" name="eta" aria-label="Ampiezza del passo eta"&gt; &lt;output name="etaOut"&gt;0.10&lt;/output&gt;&lt;/label&gt;
      &lt;label&gt;&lt;input type="checkbox" name="showOpt"&gt; mostra l'azione ottima (piccola, in alto a sinistra)&lt;/label&gt;
    &lt;/div&gt;
    &lt;div class="ql-grid"&gt;&lt;/div&gt;
    &lt;div class="ql-log" style="font-size:0.9rem;min-height:4.5em"&gt;&lt;/div&gt;
  &lt;/div&gt;`;
  const q = sel =&gt; root.querySelector(sel);
  const epsIn = q('input[name="eps"]'), etaIn = q('input[name="eta"]'), showOpt = q('input[name="showOpt"]');
  function render() {
    q('output[name="epsOut"]').textContent = (+epsIn.value).toFixed(2);
    q('output[name="etaOut"]').textContent = (+etaIn.value).toFixed(2);
    const g = grid(x =&gt; {
      const untouched = Q[x].every(v =&gt; v === 0), b = argmax(Q[x]);
      return {fill: colour(Math.max(...Q[x])), label: untouched ? "·" : arrows[eff(x, b)], current: x === s,
              corner: opt.Q[x][b] &gt;= opt.V[x] - 0.05 && !untouched ? "✓" : "", faded: untouched,
              left: showOpt.checked ? "ottima " + arrows[eff(x, opt.policy[x])] : ""};
    }, "Griglia di 20 stati che mostra l'azione attualmente preferita dall'agente in apprendimento in ciascuno.");
    q(".ql-grid").replaceChildren(g);
    const no = nearOpt(), hit = ep &gt;= 50 && no &gt;= 18;
    if (hit && window.aihs) window.aihs.complete("ch14-tryit-qlearning");
    let txt = `&lt;p&gt;Episodio &lt;strong&gt;${ep + 1}&lt;/strong&gt;, passo ${t} di ${steps} · scelta quasi ottima in &lt;strong&gt;${no} stati su 20&lt;/strong&gt;${hit ? " ✓ obiettivo raggiunto" : ""}.&lt;/p&gt;`;
    if (last) {
      const L = last;
      txt += `&lt;p&gt;${L.explore ? "Ha esplorato" : "Ha sfruttato"}: in &lt;em&gt;${lab(L.s)}&lt;/em&gt; ha scelto &lt;strong&gt;${actName[L.a]}&lt;/strong&gt; → è arrivato in &lt;em&gt;${lab(L.s2)}&lt;/em&gt;, ricompensa &lt;strong&gt;${L.r &gt; 0 ? "+" : ""}${L.r}&lt;/strong&gt;.&lt;br&gt;
      Q̂ ← ${L.old.toFixed(3)} + ${L.eta.toFixed(2)} × (${L.r} + ${gamma} × ${L.mx.toFixed(3)} − ${L.old.toFixed(3)}) = &lt;strong&gt;${L.nw.toFixed(3)}&lt;/strong&gt;.&lt;/p&gt;`;
    }
    q(".ql-log").innerHTML = txt;
  }
  root.querySelectorAll("button").forEach(btn =&gt; btn.addEventListener("click", () =&gt; {
    const n = btn.dataset.n, eps = +epsIn.value, eta = +etaIn.value;
    if (n === "reset") reset();
    else if (n === "1") step(eps, eta);
    else if (n === "ep") { do { step(eps, eta); } while (t &lt; steps); }
    else { const target = ep + (+n); while (ep &lt; target || t &lt; steps) { step(eps, eta); if (ep &gt;= target && t === steps) break; } }
    render();
  }));
  [epsIn, etaIn, showOpt].forEach(el =&gt; el.addEventListener("input", render));
