function pearson(a, b) {
  const ma = d3.mean(a), mb = d3.mean(b);
  let sab = 0, saa = 0, sbb = 0;
  for (let i = 0; i &lt; a.length; i++) { const da = a[i] - ma, db = b[i] - mb; sab += da * db; saa += da * da; sbb += db * db; }
  return sab / Math.sqrt(saa * sbb);
}
